<script setup lang="ts">
import {computed,ref,reactive,onMounted} from 'vue'
import QueryTable from '@/components/QueryTable.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
type Row=Record<string,any>
const role=computed(()=>Number(useAuthStore().effectiveRoleId))
const allowed=computed(()=>[1,2,5,6,9,10].includes(role.value))
const catalog=ref<Row>({materials:[],warehouses:[],products:[]}),result=ref<Row>(),error=ref(''),busy=ref(false)
const form=reactive({kind:'INVENTORY',material:'',warehouse:'',type:'',from:'',to:'',document:''})
async function query(){busy.value=true;error.value='';result.value=undefined;try{result.value=await request.post('/analytics/query',Object.fromEntries(Object.entries(form).filter(([k,v])=>v!==''&&(form.kind==='TRACE'?['kind','document'].includes(k):k!=='document'&&(form.kind==='INVENTORY'||!['from','to'].includes(k))))))}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{if(allowed.value)try{catalog.value=await request.get('/analytics/catalog')}catch(e:any){error.value=e.message}})
</script>
<template><details v-if="allowed" class="bg-white border rounded-xl p-5"><summary class="font-semibold cursor-pointer text-blue-700">按条件人工核对库存与追溯</summary><p class="text-sm text-slate-500 my-3">与业务智能体使用同一查询口径。选择相同的物料、仓库和日期，可核对期初、入库、出库、期末及来源批次；空余额表示历史依据不足。</p><form @submit.prevent="query" class="grid sm:grid-cols-3 gap-3"><label>查询内容<select v-model="form.kind" class="block border rounded p-2 w-full"><option value="INVENTORY">库存期间收发存</option><option value="SHORTAGE">当前缺料</option><option value="TRACE">工单／订单／计划追溯</option></select></label><template v-if="form.kind!=='TRACE'"><label>物料<select v-model="form.material" class="block border rounded p-2 w-full"><option value="">全部物料</option><option v-for="m in catalog.materials" :key="m.id" :value="String(m.id)">{{m.material_name}} · {{m.unit}}</option></select></label><label>仓库<select v-model="form.warehouse" class="block border rounded p-2 w-full"><option value="">全部仓库</option><option v-for="w in catalog.warehouses" :key="w.id" :value="String(w.id)">{{w.warehouse_name}}</option></select></label><label>类别<select v-model="form.type" class="block border rounded p-2 w-full"><option value="">全部类别</option><option value="1">原材料</option><option value="2">半成品</option><option value="3">成品</option></select></label><template v-if="form.kind==='INVENTORY'"><label>开始日期<input v-model="form.from" type="date" class="block border rounded p-2 w-full"/></label><label>结束日期<input v-model="form.to" type="date" class="block border rounded p-2 w-full"/></label></template></template><label v-else>完整单据编号<input v-model="form.document" required class="block border rounded p-2 w-full"/></label><button :disabled="busy" class="rounded bg-blue-600 text-white px-4 py-2 self-end">{{busy?'核对中…':'查询实际记录'}}</button></form><p v-if="error" role="alert" class="mt-3 text-red-700">{{error}}</p><div v-if="result" class="mt-4 space-y-3"><p class="text-sm text-slate-500">{{result.evidence}} · 查询时间 {{result.updatedAt}}</p><QueryTable :rows="result.rows||[]"/><details><summary class="text-blue-600 cursor-pointer">核对来源流水与批次</summary><QueryTable :rows="result.sources||[]"/></details></div></details></template>
